-- M7: quotas, the usage meter, and the columns retention sweeps on.
--
-- Generated by drizzle-kit, with the RLS block at the bottom added by hand —
-- the same split `0001_rls.sql` made, but in one migration rather than two on
-- purpose: a tenant table that exists for even one migration without its
-- policy is a tenant table that can be read across orgs, and `TENANT_TABLES`
-- in `schema.ts` (which the isolation test reads) would have started failing
-- the moment `usage_events` was added there.
--
-- Everything else here is additive and nullable, so it applies to a populated
-- database without a backfill: an existing video simply has no recorded size
-- until the retention sweep reconciles it against storage, and an existing org
-- has no limit overrides, which means the platform defaults in `env.ts`.

CREATE TABLE "usage_events" (
	"id" text PRIMARY KEY NOT NULL,
	"org_id" text NOT NULL,
	"kind" text NOT NULL,
	"quantity" double precision NOT NULL,
	"video_id" text,
	"export_id" text,
	"detail" text,
	"occurred_at" timestamp with time zone DEFAULT now() NOT NULL
);
