-- The ledger is tenant data like any other: the same policy, the same FORCE,
-- and the same fail-closed comparison against `app.current_org_id`. See
-- `0001_rls.sql`'s header for why the `missing_ok` form of `current_setting`
-- is the one used.
--
-- Worth naming, because it is the one table where an *escaped* read would be
-- worse than a leaked row: `usage_events` is how much a tenant has spent, and
-- the worker writes it from a process that runs every org's jobs in turn.
CREATE POLICY org_isolation ON usage_events
  USING (org_id = current_setting('app.current_org_id', true))
  WITH CHECK (org_id = current_setting('app.current_org_id', true));
